import type { FilterDataStructure, FilterValue } from 'models/Filters';
import type { AppDispatch } from 'redux/types';

export type PageUrlFilterHandlerContext = {
  searchParams: URLSearchParams;
  dataFilters: FilterDataStructure;
  defaults: Record<string, FilterValue>;
  rawData: unknown;
  dispatch: AppDispatch;
};

/** Page-specific URL → Redux handling. Registered in `pageUrlFilterHandlers.ts`. */
export type PageUrlFilterHandler = (
  context: PageUrlFilterHandlerContext,
) => void;
